INSERT INTO `tbl_chatbot_intents` (`id`, `config_id`, `intent_name`, `trigger_keywords`, `response_text`, `response_type`, `image_url`, `priority`, `is_active`, `match_count`, `created_at`, `updated_at`) VALUES
	(1, 1, 'Greeting and Help', '["hello", "hi", "hey", "good morning", "good afternoon", "good evening", "greetings", "help", "can you help me", "i need help", "assist me", "support", "hello there", "hi there", "anyone there", "are you available", "can we talk", "start chat", "start", "menu", "what can you do", "how can you help"]', 'Hi there. I can guide you through booking, package rates, services, and availability. Choose an option below or send your question.', 'quick_reply', NULL, 90, 1, 1, '2026-04-11 04:38:19', '2026-04-11 04:40:35'),
	(2, 1, 'Booking Information', '["book", "booking", "booking information", "how to book", "how do i book", "i want to book", "book now", "reserve", "reservation", "set an appointment", "appointment", "schedule", "schedule a shoot", "schedule a session", "how can i reserve", "how can i schedule", "start booking", "booking process", "booking steps", "how does booking work", "can i reserve a slot", "need to book a session"]', 'To book a session, please tell us the service you want, your preferred date, and any key details for the shoot. We will guide you through the next available schedule and package options.', 'quick_reply', NULL, 100, 1, 2, '2026-04-11 04:38:19', '2026-04-11 04:41:24'),
	(3, 1, 'Package Pricing', '["price", "pricing", "package pricing", "package rates", "rates", "rate", "cost", "package", "packages", "how much", "magkano", "how much is it", "how much are your packages", "what are your packages", "show me your packages", "package list", "price list", "pricing list", "quotation", "quote", "wedding packages", "available packages"]', 'Our package rates depend on the service type, coverage hours, and add-ons you need. If you tell us the kind of shoot you have in mind, we can guide you to the best package quickly.', 'quick_reply', NULL, 95, 1, 1, '2026-04-11 04:38:19', '2026-04-11 04:41:28'),
	(4, 1, 'Service Information', '["service", "services", "service information", "available services", "what services do you offer", "what do you offer", "offer", "offers", "shoot", "photoshoot", "photo shoot", "coverage", "studio service", "session types", "what kind of shoots do you do", "what can i book", "types of services", "studio offerings", "portrait services", "event coverage", "what sessions are available", "what packages do you offer for services"]', 'We assist clients with different photo and event-related services depending on the studio setup. Tell us the type of session you need, and we will point you to the most suitable option.', 'quick_reply', NULL, 85, 1, 2, '2026-04-11 04:38:19', '2026-04-11 04:41:13'),
	(5, 1, 'Availability and Contact', '["available", "availability", "availability and contact", "are you available", "is this date available", "do you have an open slot", "open", "open slot", "contact", "contact details", "phone", "email", "mobile number", "follow up", "follow-up", "staff", "team", "talk to your team", "how can i contact you", "can i contact the studio", "can someone call me", "schedule availability"]', 'For schedule availability or direct follow-up, please share your preferred date and session type. Our team can confirm availability and assist you with the next step.', 'quick_reply', NULL, 80, 1, 1, '2026-04-11 04:38:19', '2026-04-11 04:41:02'),
