INSERT INTO `tbl_freelancers` (`id`, `user_id`, `location_id`, `brand_name`, `tagline`, `bio`, `years_experience`, `brand_logo`, `street`, `barangay`, `service_area`, `starting_price`, `deposit_policy`, `deposit_type`, `deposit_amount`, `portfolio_works`, `facebook_url`, `instagram_url`, `website_url`, `valid_id`, `created_at`, `updated_at`) VALUES
	(2, 98, 2, 'MacroGraphy', 'Capturing Authenticity, One Frame at a Time', 'I\'m Marco Villanueva, a passionate documentary and street photographer based in Manila. With over 8 years of experience, I specialize in capturing candid, authentic moments that tell compelling visual stories. My work has been featured in local and international publications, and I\'ve collaborated with NGOs, brands, and individuals who value honest, emotion-driven photography. I believe every moment has a story worth telling, and I\'m here to help you preserve yours through timeless imagery. Whether it\'s documenting your family\'s milestones, covering your events, or creating content for your brand, I bring a journalistic eye and artistic sensibility to every project.', 8, 'brand-logos/F4DKNVKSmBCwfVVcbgpJHOsr70VN5jPi3ea4DRoF.png', 'Unit 12B, Urban Residences, 789 Roxas Boulevard', 'Tejero', 'Within my city only', 3500.00, 'not_required', 'fixed', 0.00, '"[\\"portfolio-works\\\\\\/TGMaEw723DQdWLQ9VPvpxSoIITN8D7lGgi7lelfN.png\\",\\"portfolio-works\\\\\\/aEzmtcMRcqHcbYXuzlsGEzLxAWYQztxFx3dGVpxT.png\\",\\"portfolio-works\\\\\\/HKE7UC9Egp8R92ACucSOvlu6BdTa51Teu03kVAHZ.png\\",\\"portfolio-works\\\\\\/p3FmAZhXAAssCXdMF71UgmXkbMjNsgS9qDsMMwGy.png\\",\\"portfolio-works\\\\\\/XjdAJWmce7Df1nQBjW21Tn8MpoK94FkTU09iWTGu.png\\",\\"portfolio-works\\\\\\/kXcPqTSpzKaPfYlHq9TdGOGr45MS2GzTOeH2NPkZ.png\\"]"', 'https://www.facebook.com/marcovphotography', 'https://www.instagram.com/marco.v.photo', 'https://www.marcovphotography.com/', 'valid-ids/DKbpiUIVbhwZdBvsfUMZ2gcMG89Jo2SbrgOnT1DD.jpg', '2026-02-26 23:26:55', '2026-02-26 23:26:55'),
	(3, 214, 6, 'Everlight Stories', 'Warm portraits for milestone celebrations', 'Elena specializes in wedding and family portrait sessions with a bright, timeless editing style that balances guided posing and candid storytelling.', 7, 'brand-logos/F4DKNVKSmBCwfVVcbgpJHOsr70VN5jPi3ea4DRoF.png', 'Blk 8 Lot 14, Garden Villas', 'Bayan Luma III', 'Cavite and nearby Metro Manila cities', 4500.00, 'required', 'percentage', 30.00, '["portfolio-works\\/seed-everlight-1.png","portfolio-works\\/seed-everlight-2.png","portfolio-works\\/seed-everlight-3.png"]', 'https://facebook.com/everlightstories', 'https://instagram.com/everlightstories', 'https://everlightstories.test', 'valid-ids/seed-everlight-id.jpg', '2026-04-19 13:18:32', '2026-04-19 13:18:32'),
	(4, 215, 2, 'Streetframe Works', 'Fast, candid coverage for live events and brands', 'Marco focuses on event and street-inspired brand coverage, delivering high-energy documentary style imagery for launches, activations, and celebrations.', 6, 'brand-logos/F4DKNVKSmBCwfVVcbgpJHOsr70VN5jPi3ea4DRoF.png', 'Unit 5, Ferrer Business Strip', 'Manggahan', 'General Trias, Cavite, Metro Manila', 3800.00, 'required', 'fixed', 2000.00, '["portfolio-works\\/seed-streetframe-1.png","portfolio-works\\/seed-streetframe-2.png","portfolio-works\\/seed-streetframe-3.png"]', 'https://facebook.com/streetframeworks', 'https://instagram.com/streetframeworks', 'https://streetframeworks.test', 'valid-ids/seed-streetframe-id.jpg', '2026-04-19 13:18:32', '2026-04-19 13:18:32'),
	(5, 216, 7, 'Mode Studio Social', 'Editorial fashion and campaign imagery', 'Sofia works with designers, small labels, and personal brands to produce sharp editorial visuals and lookbook-ready sets with clean, premium retouching.', 8, 'brand-logos/F4DKNVKSmBCwfVVcbgpJHOsr70VN5jPi3ea4DRoF.png', 'Lot 2, Creative Grove', 'Balite II', 'Silang, Tagaytay, Metro Manila', 5200.00, 'required', 'percentage', 40.00, '["portfolio-works\\/seed-mode-1.png","portfolio-works\\/seed-mode-2.png","portfolio-works\\/seed-mode-3.png"]', 'https://facebook.com/modestudiosocial', 'https://instagram.com/modestudiosocial', 'https://modestudiosocial.test', 'valid-ids/seed-mode-id.jpg', '2026-04-19 13:18:33', '2026-04-19 13:18:33'),
	(6, 217, 18, 'HomeLight Portrait Co.', 'Comfort-first portraits for families and pets', 'Paolo creates relaxed portrait sessions for families, kids, and pets, with an emphasis on natural expressions, gentle pacing, and polished delivery sets.', 5, 'brand-logos/F4DKNVKSmBCwfVVcbgpJHOsr70VN5jPi3ea4DRoF.png', '12 Paseo Carmona Residences', 'Maduya', 'Carmona, Cavite, Alabang', 4000.00, 'not_required', 'fixed', 0.00, '["portfolio-works\\/seed-homelight-1.png","portfolio-works\\/seed-homelight-2.png","portfolio-works\\/seed-homelight-3.png"]', 'https://facebook.com/homelightportraitco', 'https://instagram.com/homelightportraitco', 'https://homelightportraitco.test', 'valid-ids/seed-homelight-id.jpg', '2026-04-19 13:18:33', '2026-04-19 13:18:33'),
	(7, 218, 21, 'Lens & Land Creative', 'Places, products, and polished campaign frames', 'Tessa delivers structured commercial sessions for property, product, and food clients who need consistent image sets for catalogs, listings, and promotional campaigns.', 9, 'brand-logos/F4DKNVKSmBCwfVVcbgpJHOsr70VN5jPi3ea4DRoF.png', 'Harbor View Commercial Row', 'Tabon II', 'Kawit, Cavite, Metro Manila', 5600.00, 'required', 'fixed', 3000.00, '["portfolio-works\\/seed-lensland-1.png","portfolio-works\\/seed-lensland-2.png","portfolio-works\\/seed-lensland-3.png"]', 'https://facebook.com/lensandlandcreative', 'https://instagram.com/lensandlandcreative', 'https://lensandlandcreative.test', 'valid-ids/seed-lensland-id.jpg', '2026-04-19 13:18:33', '2026-04-19 13:18:33');
