INSERT INTO `tbl_roles` (`id`, `name`, `portal`, `description`, `status`, `is_system`, `created_at`, `updated_at`) VALUES
	(1, 'owner-super-admin', 'owner', 'Full owner portal access across studio management modules.', 'active', 1, '2026-04-05 14:11:39', '2026-04-19 13:46:17'),
	(2, 'studio-hr-manager', 'studio-hr', 'Oversees all human resources functions in the studio, including hiring, employee relations, policy implementation, and performance management. Ensures a positive work environment and compliance with labor laws.', 'active', 1, '2026-04-05 14:11:39', '2026-04-19 13:46:17'),
	(3, 'studio-hr-staff', 'studio-hr', 'Supports HR operations by assisting with recruitment, onboarding, maintaining employee records, and handling basic employee concerns. Works under the HR Manager.', 'active', 1, '2026-04-05 14:11:39', '2026-04-19 13:46:17'),
	(4, 'studio-finance-manager', 'studio-finance', 'Manages the studio\'s financial activities such as budgeting, financial planning, reporting, and expense control. Ensures the studio stays financially healthy and compliant with regulations.', 'active', 1, '2026-04-05 14:11:39', '2026-04-19 13:46:17'),
	(5, 'studio-finance-staff', 'studio-finance', 'Handles day-to-day financial tasks like processing payments, recording transactions, preparing invoices, and assisting with financial reports under the Finance Manager.', 'active', 1, '2026-04-05 14:11:39', '2026-04-19 13:46:17'),
	(6, 'studio-photographer', 'studio-photographer', 'Captures photos for studio projects, including shoots, editing, and ensuring high-quality visual output that meets client or creative requirements.', 'active', 1, '2026-04-05 14:11:39', '2026-04-19 13:46:17');
