INSERT INTO `tbl_studios` (`id`, `user_id`, `category_id`, `location_id`, `street`, `barangay`, `attendance_latitude`, `attendance_longitude`, `attendance_radius_meters`, `contact_number`, `studio_email`, `facebook_url`, `instagram_url`, `website_url`, `studio_name`, `studio_type`, `year_established`, `studio_description`, `studio_logo`, `starting_price`, `downpayment_percentage`, `operating_days`, `start_time`, `end_time`, `max_clients_per_day`, `advance_booking_days`, `business_permit`, `owner_id_document`, `status`, `rejection_note`, `created_at`, `updated_at`) VALUES
	(1, 96, 1, 1, 'Unit 402, 4th Floor, Valero Tower, 122 Valero St.', 'Salitran III', 14.3291121, 120.9410593, 30, '09171234567', 'hello@prismandpine.com', 'https://facebook.com/prismandpinestudio', 'https://instagram.com/prismandpine', 'https://www.prismandpine.com', 'Prism & Pine Creative Spaces', 'photography_studio', 2022, 'A 120sqm minimalist, Scandinavian-inspired daylight studio located in the heart of the city. We specialize in editorial fashion, high-end portraits, and commercial product shoots. Our space features floor-to-ceiling windows, a motorized cyclorama wall, and a dedicated makeup and dressing area.', 'studio_logo/0ebd87e6-4dd2-4d74-a7aa-8ed3675fe311.png', '3500', 67.00, '["monday","wednesday","friday","saturday"]', '08:00:00', '18:00:00', 4, 3, 'studio_documents/943b5df4-4eda-4b65-9ca0-504ce5e79fa8.pdf', 'studio_documents/016bf19e-a03b-41db-bbea-bd122b1baa7c.jpg', 'verified', NULL, '2026-02-24 20:10:55', '2026-04-19 13:41:43'),
	(4, 165, 1, 6, '2F Solis Arcade, Aguinaldo Highway', 'Bucandala III', 14.4091123, 120.9402451, 50, '09172010001', 'hello@auroraweddinghouse.test', 'https://facebook.com/auroraweddinghouse', 'https://instagram.com/auroraweddinghouse', 'https://auroraweddinghouse.test', 'Aurora Wedding House', 'photography_studio', 2021, 'A bright, full-service studio brand focused on elegant wedding stories and polished event documentation for modern celebrations across Cavite.', 'studio_logo/c1710bab-033b-406c-8d1b-ff5f0de43d80.png', '6500', 40.00, '["tuesday","wednesday","thursday","friday","saturday"]', '09:00:00', '18:00:00', 4, 3, 'studio_documents/seed-aurora-business-permit.pdf', 'studio_documents/seed-aurora-owner-id.pdf', 'verified', NULL, '2026-04-19 12:42:15', '2026-04-19 13:46:25'),
	(5, 181, 3, 7, 'The Courtyard, Emilio Aguinaldo Highway', 'Mataas Na Burol', 14.2318821, 120.9743015, 45, '09172010002', 'contact@northframecollective.test', 'https://facebook.com/northframecollective', 'https://instagram.com/northframecollective', 'https://northframecollective.test', 'North Frame Collective', 'photography_studio', 2020, 'A lifestyle-forward creative studio known for warm family portrait sessions, fashion editorials, and clean art direction for growing brands.', 'studio_logo/c1710bab-033b-406c-8d1b-ff5f0de43d80.png', '4200', 35.00, '["monday","wednesday","thursday","friday","saturday"]', '10:00:00', '19:00:00', 5, 2, 'studio_documents/seed-northframe-business-permit.pdf', 'studio_documents/seed-northframe-owner-id.pdf', 'verified', NULL, '2026-04-19 12:42:23', '2026-04-19 13:46:31'),
	(6, 197, 4, 2, 'Ground Floor, Evo Marketplace, Arnaldo Highway', 'Manggahan', 14.3612334, 120.8824543, 60, '09172010003', 'studio@goldenlenshouse.test', 'https://facebook.com/goldenlenshouse', 'https://instagram.com/goldenlenshouse', 'https://goldenlenshouse.test', 'Golden Lens House', 'mixed_media', 2023, 'A compact production house built for product staging and pet portrait sessions, combining commercial discipline with playful, client-friendly studio handling.', 'studio_logo/c1710bab-033b-406c-8d1b-ff5f0de43d80.png', '3800', 30.00, '["tuesday","wednesday","thursday","friday","saturday","sunday"]', '08:30:00', '17:30:00', 6, 2, 'studio_documents/seed-goldenlens-business-permit.pdf', 'studio_documents/seed-goldenlens-owner-id.pdf', 'verified', NULL, '2026-04-19 12:42:30', '2026-04-19 13:46:58');
